#include <bits/stdc++.h>
#define IOS ios::sync_with_stdio(0)
#define lowbit(x) ((x) & (-x))
#define int long long
using namespace std;

inline char read_char() {
    static char buf[1000000], *p1 = buf, *p2 = buf;
    return p1 == p2 && (p2 = (p1 = buf) + fread(buf, 1, 1000000, stdin), p1 == p2) ? EOF : *p1++;
}

int read_int() {
    int sign = 1, res = 0;
    char ch = read_char();
    while (!isdigit(ch)) {
        if (ch == '-') sign = -1;
        ch = read_char();
    }
    while (isdigit(ch)) {
        res = res * 10 + (ch - '0');
        ch = read_char();
    }
    return sign * res;
}

void print_num(int x) {
    if (x < 0) {
        putchar('-');
        print_num(-x);
        return;
    }
    if (x >= 10) print_num(x / 10);
    putchar(x % 10 + '0');
}

void print_with_space(int x) {
    print_num(x);
    putchar(' ');
}

void print_with_newline(int x) {
    print_num(x);
    putchar('\n');
}

const int MODX = 998244353, MODY = 1000000007;
vector<int> val[10];
int n, countA, countB, answer, sumArr[10], powArr[7] = {1, 10, 100, 1000, 10000, 100000, 1000000};

bool checkX(int x) {
    int limit = 1000000;
    return x * limit + 999999 <= n && x * limit * 10 > n;
}

void generate(int depth, int prefix) {
    if (depth == 7) return;
    val[depth].push_back((countA - prefix + MODX) % MODX);
    sumArr[depth] += (countA - prefix + MODX) % MODX;
    countA++;
    for (int d = 0; d <= 9; d++)
        generate(depth + 1, prefix * 10 + d);
}

void process(int depth, int current) {
    if (current > n) return;
    if (checkX(current)) {
        for (int i = 0; i <= 6; i++) {
            int temp = ((countB + 1 - (current * powArr[i])) % MODX + MODX) % MODX;
            int pos = lower_bound(val[i].begin(), val[i].end(), MODX - temp) - val[i].begin();
            answer = (answer + (sumArr[i] + temp * (int)val[i].size() - MODX * ((int)val[i].size() - pos))) % MODY;
        }
        countB += countA;
    } else {
        countB++;
        answer = (answer + ((countB - current) % MODX + MODX) % MODX) % MODY;
        for (int d = (!depth); d <= 9; d++)
            process(depth + 1, current * 10 + d);
    }
}

int main() {
    n = read_int();
    generate(0, 0);
    for (int i = 0; i <= 6; i++)
        sort(val[i].begin(), val[i].end());
    countB = -1;
    process(0, 0);
    print_with_newline(answer);
}
